/* ============================================================
   DRAWER
   ============================================================ */

.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 55;
  background: rgba(2, 5, 8, 0.68);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.drawer-backdrop.is-visible {
  opacity: 1;
}

.drawer {
  position: fixed;
  top: 0;
  right: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  width: min(540px, 94vw);
  height: 100vh;
  height: 100dvh;
  padding: 26px clamp(20px, 5vw, 36px);
  overflow-y: auto;
  border-left: 1px solid var(--line-strong);
  background:
    radial-gradient(ellipse 100% 30% at 100% 0%, rgba(34, 61, 78, 0.25), transparent 70%),
    #081017;
  box-shadow: -30px 0 80px rgba(0, 0, 0, 0.5);
  transform: translateX(102%);
  transition: transform 0.48s var(--ease);
  overscroll-behavior: contain;
}

.drawer.is-open {
  transform: translateX(0);
}

.drawer-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.drawer-kicker {
  color: var(--amber);
}

.drawer-title {
  margin: 8px 0 0;
  font-family: var(--serif);
  font-size: 2.3rem;
  font-weight: 400;
  line-height: 1;
  color: var(--snow);
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--muted);
  font-size: 0.8rem;
  transition: border-color 0.3s, color 0.3s;
}

.icon-btn:hover {
  border-color: var(--line-strong);
  color: var(--snow);
}

.drawer-intro {
  margin: 18px 0 0;
  font-family: var(--prose);
  font-size: 0.86rem;
  font-weight: 300;
  line-height: 1.65;
  color: var(--text-soft);
}

.drawer-progress {
  margin: 12px 0 4px;
  font-size: 0.53rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--faint);
}

.notes-list {
  margin-top: 10px;
}

.note {
  padding: 18px 0;
  border-bottom: 1px solid var(--line);
}

.note.is-locked {
  opacity: 0.38;
}

.note-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.note-index {
  font-size: 0.52rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  color: var(--amber);
  font-variant-numeric: tabular-nums;
}

.note-title {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.18rem;
  font-weight: 500;
  line-height: 1.25;
  color: var(--snow);
}

.note-body {
  margin: 8px 0 0;
  font-family: var(--prose);
  font-size: 0.86rem;
  font-weight: 300;
  line-height: 1.72;
  color: #b7c8d5;
}

.note-source {
  margin: 7px 0 0;
  font-size: 0.5rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--faint);
}

.note.is-locked .note-body {
  display: none;
}

.drawer-foot {
  margin-top: auto;
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

.drawer-foot p {
  margin: 0 0 12px;
  font-family: var(--prose);
  font-size: 0.72rem;
  font-weight: 300;
  line-height: 1.65;
  color: var(--faint);
}

.drawer-foot strong {
  color: var(--muted);
  font-weight: 500;
}

/* ============================================================
   CONFIRM MODAL + TOAST
   ============================================================ */

.modal {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(2, 5, 8, 0.72);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.modal-card {
  width: min(430px, 100%);
  padding: 30px;
  border: 1px solid var(--line-strong);
  background: #0a1219;
  box-shadow: var(--shadow);
}

.modal-card h2 {
  margin: 12px 0 12px;
  font-family: var(--serif);
  font-size: 1.9rem;
  font-weight: 400;
  line-height: 1.15;
  color: var(--snow);
}

.modal-card > p:not(.modal-kicker) {
  margin: 0;
  font-family: var(--prose);
  font-size: 0.86rem;
  font-weight: 300;
  line-height: 1.65;
  color: var(--text-soft);
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}

.toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 80;
  max-width: 300px;
  padding: 11px 15px;
  border: 1px solid var(--line-strong);
  background: rgba(9, 17, 24, 0.96);
  font-size: 0.55rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1.5;
  text-transform: uppercase;
  color: var(--ice-bright);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
  transition: opacity 0.35s, transform 0.35s;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

