```js
function ensureAudio() {
  if (audio) return audio;
  const Ctx = window.AudioContext || window.webkitAudioContext;
  if (!Ctx) return null;
  const ctx = new Ctx();
  const buffer = ctx.createBuffer(1, ctx.sampleRate*4, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  let last = 0;
  for (let i=0;i<data.length;i++){ const white=Math.random()*2-1; last=(last+0.02*white)/1.02; data[i]=last*3.5; }
  const noise = ctx.createBufferSource(); noise.buffer=buffer; noise.loop=true;
  const filter = ctx.createBiquadFilter(); filter.type='bandpass'; filter.frequency.value=500; filter.Q.value=0.7;
  const gain = ctx.createGain(); gain.gain.value=0;
  noise.connect(filter); filter.connect(gain); gain.connect(ctx.destination);
  noise.start();
  const osc = ctx.createOscillator(); osc.type='sine'; osc.frequency.value=52;
  const oscGain = ctx.createGain(); oscGain.gain.value=0;
  osc.connect(oscGain); oscGain.connect(ctx.destination); osc.start();
  audio = {ctx, gain, oscGain};
  return audio;
}
function setSound(on, opts={}) {
  soundOn = on;
  if (on) {
    const a = ensureAudio();
    if (a) { a.ctx.resume(); a.gain.gain.setTargetAtTime(0.055, a.ctx.currentTime, 0.8); a.oscGain.gain.setTargetAtTime(0.018, a.ctx.currentTime, 0.8); }
    writeJSON(SOUND_KEY, true)? Use localStorage.setItem(SOUND_KEY,'1').
  } else {
    if (audio) { audio.gain.gain.setTargetAtTime(0, audio.ctx.currentTime, 0.4); audio.oscGain.gain.setTargetAtTime(0, audio.ctx.currentTime, 0.4); }
    localStorage.setItem(SOUND_KEY,'0');
  }
  updateSoundButton();
}
