cd /home/runner/work/Game/Game && node --input-type=module -e '
import { STORY, ACTS, NOTES, SURVIVORS, LOST } from "./js/story.js";
const ids = new Set(Object.keys(STORY.nodes));
const errors = [];
const reachable = new Set();
const flagSets = new Set();
const flagReads = new Set();
const notesUsed = new Set();
function checkNext(next, from){
  if(!next) return;
  if(typeof next === "string"){ if(!ids.has(next)) errors.push(`missing next ${from} -> ${next}`); return; }
  for(const k of ["then","otherwise"]) if(next[k] && !ids.has(next[k])) errors.push(`missing next ${from} -> ${next[k]}`);
  if(next.ifFlag) flagReads.add(next.ifFlag);
  if(next.ifStat && !["warmth","strength","hope"].includes(next.ifStat)) errors.push(`bad stat ${from} ${next.ifStat}`);
}
for(const [id,node] of Object.entries(STORY.nodes)){
  if(node.note){ notesUsed.add(node.note); if(!NOTES[node.note]) errors.push(`missing note ${node.note} in ${id}`); }
  const choices = node.choices || [];
  if(!choices.length && node.kind!=="ending" && node.kind!=="death") errors.push(`no choices in ${id}`);
  for(const ch of choices){
    checkNext(ch.next,id);
    if(ch.set) Object.keys(ch.set).forEach(f=>flagSets.add(f));
    if(ch.if) flagReads.add(ch.if);
    if(ch.third && !["Tintín","Roy"].includes(ch.third)) errors.push(`bad third ${id}`);
  }
  for(const p of node.text){
    if(typeof p==="object"){
      if(p.if) flagReads.add(p.if);
      if(p.unless) flagReads.add(p.unless);
    }
  }
  if(node.text.some(p=>typeof p==="string" && p.includes("{{third}}"))) flagReads.add("__third");
}
// reachability
const stack=[STORY.start];
while(stack.length){
  const id=stack.pop();
  if(reachable.has(id)) continue;
  reachable.add(id);
  const node=STORY.nodes[id];
  for(const ch of node.choices||[]){
    const nexts=[];
    if(typeof ch.next==="string") nexts.push(ch.next);
    else if(ch.next){ if(ch.next.then) nexts.push(ch.next.then); if(ch.next.otherwise) nexts.push(ch.next.otherwise); }
    nexts.forEach(n=>{ if(ids.has(n)) stack.push(n); });
  }
}
for(const id of ids) if(!reachable.has(id)) errors.push(`unreachable node ${id}`);
for(const id of notesUsed) if(!NOTES[id]) errors.push(`note missing ${id}`);
const unusedNotes=Object.keys(NOTES).filter(n=>!notesUsed.has(n));
if(unusedNotes.length) errors.push(`unused notes: ${unusedNotes.join(", ")}`);
const neverSet=[...flagReads].filter(f=>f!=="__third"&&!flagSets.has(f));
if(neverSet.length) errors.push(`flags read but never set: ${neverSet.join(", ")}`);
console.log("nodes",ids.size,"reachable",reachable.size,"notes",notesUsed.size,"survivors",SURVIVORS.length,"lost",LOST.length);
console.log("deaths",Object.values(STORY.nodes).filter(n=>n.kind==="death").length);
console.log(errors.length?errors.join("\n"):"OK");
'

